parameters.jsCode:
const src = $json || {};
const cfg = src.kb01b1_cfg || {};

const base = {
  operaciya_id: src.operaciya_id ?? null,
  rezultat: src.rezultat ?? null,
  kod_oshibki: src.kod_oshibki ?? null,
  opisanie: src.opisanie ?? null,
  zadanie_id: src.zadanie_id ?? null,
  zagruzka_id: src.zagruzka_id ?? null,
  dokument_id: src.dokument_id ?? null,
  status_zadaniya: src.status_zadaniya ?? null,
  popytki: src.popytki ?? null,
  vladelec_arendy: src.vladelec_arendy ?? null,
  arenda_do: src.arenda_do ?? null,
  nomer_vladeniya: src.nomer_vladeniya ?? null,
  imya_fayla: src.imya_fayla ?? null,
  hash_istochnika: src.hash_istochnika ?? null,
  kb01b1_cfg: cfg
};

if (String(src.rezultat || '') !== 'uspeshno' || !src.zadanie_id) {
  return [{ json: {
    ...base,
    kb01b1_est_zadanie: false,
    kb01b1_valid: false,
    kb01b1_kod: String(src.rezultat || '') === 'net_zadaniya' ? 'net_zadaniya' : (src.kod_oshibki || 'claim_ne_uspeshno'),
    kb01b1_opisanie: src.opisanie || 'Knowledge job не получен.'
  }}];
}

function fail(code, message, details = {}) {
  return [{ json: {
    ...base,
    kb01b1_est_zadanie: true,
    kb01b1_valid: false,
    kb01b1_kod: code,
    kb01b1_opisanie: message,
    kb01b1_detali: details
  }}];
}

function toBytes(v) {
  if (v == null) throw new Error('ishodnyy_fayl отсутствует');
  if (v instanceof Uint8Array) return v;
  if (Array.isArray(v)) return Uint8Array.from(v);
  if (typeof v === 'object') {
    if (v.type === 'Buffer' && Array.isArray(v.data)) return Uint8Array.from(v.data);
    if (Array.isArray(v.data)) return Uint8Array.from(v.data);
  }
  if (typeof v === 'string') {
    const s = v.trim();
    if (/^\\x[0-9a-f]+$/i.test(s) && (s.length - 2) % 2 === 0) {
      const hex = s.slice(2);
      const a = new Uint8Array(hex.length / 2);
      for (let i = 0; i < a.length; i++) a[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
      return a;
    }
    if (/^[A-Za-z0-9+/]+={0,2}$/.test(s) && s.length % 4 === 0) {
      const bin = atob(s);
      return Uint8Array.from(bin, c => c.charCodeAt(0));
    }
  }
  throw new Error('Неподдерживаемый формат bytea из Postgres');
}

const K = [
  0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
  0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
  0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
  0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
  0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
  0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
  0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
  0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
];
const rotr = (x,n) => (x >>> n) | (x << (32-n));
function sha256Bytes(bytes) {
  const bitLen = bytes.length * 8;
  const pad = (64 - ((bytes.length + 1 + 8) % 64)) % 64;
  const msg = new Uint8Array(bytes.length + 1 + pad + 8);
  msg.set(bytes);
  msg[bytes.length] = 0x80;
  const hi = Math.floor(bitLen / 0x100000000);
  const lo = bitLen >>> 0;
  const o = msg.length - 8;
  msg[o]=(hi>>>24)&255; msg[o+1]=(hi>>>16)&255; msg[o+2]=(hi>>>8)&255; msg[o+3]=hi&255;
  msg[o+4]=(lo>>>24)&255; msg[o+5]=(lo>>>16)&255; msg[o+6]=(lo>>>8)&255; msg[o+7]=lo&255;
  let h=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const w = new Uint32Array(64);
  for (let off=0; off<msg.length; off+=64) {
    for (let i=0;i<16;i++) {
      const j=off+i*4;
      w[i]=((msg[j]<<24)|(msg[j+1]<<16)|(msg[j+2]<<8)|msg[j+3])>>>0;
    }
    for (let i=16;i<64;i++) {
      const a=w[i-15], b=w[i-2];
      const s0=(rotr(a,7)^rotr(a,18)^(a>>>3))>>>0;
      const s1=(rotr(b,17)^rotr(b,19)^(b>>>10))>>>0;
      w[i]=(w[i-16]+s0+w[i-7]+s1)>>>0;
    }
    let [a,b,c,d,e,f,g,hh]=h;
    for (let i=0;i<64;i++) {
      const S1=(rotr(e,6)^rotr(e,11)^rotr(e,25))>>>0;
      const ch=((e&f)^((~e)&g))>>>0;
      const t1=(hh+S1+ch+K[i]+w[i])>>>0;
      const S0=(rotr(a,2)^rotr(a,13)^rotr(a,22))>>>0;
      const maj=((a&b)^(a&c)^(b&c))>>>0;
      const t2=(S0+maj)>>>0;
      hh=g; g=f; f=e; e=(d+t1)>>>0; d=c; c=b; b=a; a=(t1+t2)>>>0;
    }
    h=[(h[0]+a)>>>0,(h[1]+b)>>>0,(h[2]+c)>>>0,(h[3]+d)>>>0,(h[4]+e)>>>0,(h[5]+f)>>>0,(h[6]+g)>>>0,(h[7]+hh)>>>0];
  }
  return h.map(x=>x.toString(16).padStart(8,'0')).join('');
}
function sha256Hex(text) { return sha256Bytes(new TextEncoder().encode(text)); }

function parseScalar(raw) {
  const s = String(raw ?? '').trim();
  if (!s) return '';
  if (s.startsWith('!') || s.startsWith('&') || s.startsWith('*') || s === '|' || s === '>' || s.startsWith('{') || s.startsWith('[')) {
    throw new Error('Неподдерживаемая или небезопасная YAML-конструкция');
  }
  if (s.startsWith('"')) {
    if (!s.endsWith('"')) throw new Error('Незакрытая двойная кавычка YAML');
    try { return JSON.parse(s); } catch { throw new Error('Некорректная строка в двойных кавычках YAML'); }
  }
  if (s.startsWith("'")) {
    if (!s.endsWith("'")) throw new Error('Незакрытая одинарная кавычка YAML');
    return s.slice(1,-1).replace(/''/g,"'");
  }
  return s;
}

function parseFrontMatter(front, maxLines, maxQuestions) {
  const lines = front.split('\n');
  if (lines.length > maxLines) throw new Error('YAML превышает допустимое число строк');
  if (lines.some(l=>l.includes('\t'))) throw new Error('Табуляция в YAML запрещена');
  const allowedTop = new Set(['identifikator_dokumenta','nazvanie','tip_dokumenta','versiya_istochnika','data_obnovleniya','kontrolnye_voprosy']);
  const allowedQ = new Set(['vopros','ozhidaemyy_razdel','ozhidaemyy_fakt']);
  const meta = {};
  const seenTop = new Set();
  let i=0;
  while (i<lines.length) {
    const line=lines[i];
    if (!line.trim()) { i++; continue; }
    if (/^\s/.test(line)) throw new Error(`Неожиданный отступ YAML в строке ${i+1}`);
    const m=line.match(/^([a-z_][a-z0-9_]*):(?:\s*(.*))?$/);
    if (!m) throw new Error(`Неподдерживаемый YAML в строке ${i+1}`);
    const key=m[1], raw=m[2]??'';
    if (!allowedTop.has(key)) throw new Error(`Неизвестное поле YAML: ${key}`);
    if (seenTop.has(key)) throw new Error(`Дублирующийся ключ YAML: ${key}`);
    seenTop.add(key);
    if (key!=='kontrolnye_voprosy') {
      meta[key]=parseScalar(raw);
      i++;
      continue;
    }
    if (raw.trim() && raw.trim() !== '[]') throw new Error('kontrolnye_voprosy должен быть YAML-списком');
    if (raw.trim() === '[]') { meta.kontrolnye_voprosy=[]; i++; continue; }
    const qs=[];
    i++;
    while (i<lines.length && (/^\s/.test(lines[i]) || !lines[i].trim())) {
      if (!lines[i].trim()) { i++; continue; }
      const first=lines[i].match(/^  -(?:\s+([a-z_][a-z0-9_]*):(?:\s*(.*))?)?$/);
      if (!first) throw new Error(`Некорректный элемент kontrolnye_voprosy в строке ${i+1}`);
      const q={}, seenQ=new Set();
      if (first[1]) {
        if (!allowedQ.has(first[1])) throw new Error(`Неизвестное поле вопроса: ${first[1]}`);
        seenQ.add(first[1]); q[first[1]]=parseScalar(first[2]??'');
      }
      i++;
      while (i<lines.length) {
        if (!lines[i].trim()) { i++; continue; }
        const mm=lines[i].match(/^    ([a-z_][a-z0-9_]*):(?:\s*(.*))?$/);
        if (!mm) break;
        if (!allowedQ.has(mm[1])) throw new Error(`Неизвестное поле вопроса: ${mm[1]}`);
        if (seenQ.has(mm[1])) throw new Error(`Дублирующееся поле вопроса: ${mm[1]}`);
        seenQ.add(mm[1]); q[mm[1]]=parseScalar(mm[2]??'');
        i++;
      }
      qs.push(q);
      if (qs.length>maxQuestions) throw new Error(`Контрольных вопросов больше ${maxQuestions}`);
    }
    meta.kontrolnye_voprosy=qs;
  }
  if (!('kontrolnye_voprosy' in meta)) meta.kontrolnye_voprosy=[];
  return meta;
}

function normTitle(s) {
  return String(s||'').normalize('NFC').toLowerCase().replace(/[`*_~\[\]()]/g,' ').replace(/[—–-]/g,' ').replace(/[^a-zа-яё0-9]+/giu,' ').trim().replace(/\s+/g,' ');
}

let bytes, text;
try {
  bytes=toBytes(src.ishodnyy_fayl);
  text=new TextDecoder('utf-8',{fatal:true}).decode(bytes);
} catch (e) {
  return fail('kb01b1_ne_utf8_ili_bytea', String(e.message||e));
}

const actualSourceHash=sha256Bytes(bytes);
if (src.hash_istochnika && actualSourceHash !== String(src.hash_istochnika).toLowerCase()) {
  return fail('kb01b1_hash_istochnika_ne_sovpadaet','Hash исходных bytes не совпал с DB registration.',{actualSourceHash});
}

text=text.replace(/^\uFEFF/,'').replace(/\r\n?/g,'\n').normalize('NFC');
if (!text.startsWith('---\n')) return fail('kb01b1_net_yaml','Файл должен начинаться с YAML front matter `---`.');
const close=text.indexOf('\n---\n',4);
if (close<0) return fail('kb01b1_yaml_ne_zakryt','Не найден закрывающий `---` YAML front matter.');
const front=text.slice(4,close);
let body=text.slice(close+5);

let meta;
try {
  meta=parseFrontMatter(front, Number(cfg.max_yaml_strok||300), Number(cfg.max_kontrolnyh_voprosov||10));
} catch(e) {
  return fail('kb01b1_yaml_nevaliden',String(e.message||e));
}

const allowedTypes=new Set(['opisanie','harakteristiki','instrukciya','faq','usloviya','politika']);
if (!/^[a-z][a-z0-9_]{0,79}$/.test(meta.identifikator_dokumenta||'')) return fail('kb01b1_identifikator_nevaliden','identifikator_dokumenta не соответствует формату v1.');
if (!String(meta.nazvanie||'').trim()) return fail('kb01b1_nazvanie_pustoe','nazvanie обязательно.');
if (!allowedTypes.has(meta.tip_dokumenta)) return fail('kb01b1_tip_nevaliden','tip_dokumenta не входит в разрешённый список.');
if (meta.data_obnovleniya) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(meta.data_obnovleniya)) return fail('kb01b1_data_nevalidna','data_obnovleniya должна иметь формат YYYY-MM-DD.');
  const d=new Date(meta.data_obnovleniya+'T00:00:00Z');
  if (!Number.isFinite(d.getTime()) || d.toISOString().slice(0,10)!==meta.data_obnovleniya) return fail('kb01b1_data_nevalidna','data_obnovleniya не является календарной датой.');
}
for (let qi=0;qi<meta.kontrolnye_voprosy.length;qi++) {
  const q=meta.kontrolnye_voprosy[qi];
  if (!String(q.vopros||'').trim() || !String(q.ozhidaemyy_razdel||'').trim()) return fail('kb01b1_vopros_nevaliden',`Контрольный вопрос ${qi+1} требует vopros и ozhidaemyy_razdel.`);
}

body=body.replace(/[ \t]+$/gm,'').replace(/^\n+/,'').replace(/\n+$/,'');
const lines=body.split('\n');
let fence=null, headings=[], prevLevel=0;
for (let i=0;i<lines.length;i++) {
  const line=lines[i];
  const fm=line.match(/^\s*(`{3,}|~{3,})/);
  if (fm) {
    const token=fm[1];
    if (!fence) fence={ch:token[0],len:token.length};
    else if (token[0]===fence.ch && token.length>=fence.len) fence=null;
    continue;
  }
  if (fence) continue;
  const hm=line.match(/^(#{1,6})[ \t]+(.+?)\s*#*\s*$/);
  if (!hm) continue;
  const level=hm[1].length;
  const title=hm[2].trim();
  if (!title) return fail('kb01b1_pustoy_zagolovok',`Пустой заголовок в строке ${i+1}.`);
  if (headings.length===0 && level!==1) return fail('kb01b1_pervyy_zagolovok_ne_h1','Первый структурный заголовок должен быть H1.');
  if (prevLevel && level>prevLevel+1) return fail('kb01b1_propusk_urovnya',`Пропущен уровень заголовка перед строкой ${i+1}.`,{predydushchiy:prevLevel,tekushchiy:level});
  headings.push({level,title,line:i+1}); prevLevel=level;
}
if (fence) return fail('kb01b1_kod_blok_ne_zakryt','В Markdown не закрыт fenced code block.');
const h1=headings.filter(h=>h.level===1);
if (h1.length!==1) return fail('kb01b1_h1_kolichestvo',`Ожидается ровно один H1, найдено ${h1.length}.`);
if (normTitle(h1[0].title)!==normTitle(meta.nazvanie)) return fail('kb01b1_h1_ne_sovpadaet','H1 не совпадает по нормализованному смысловому тексту с nazvanie.',{h1:h1[0].title,nazvanie:meta.nazvanie});

const canonicalMeta={
  identifikator_dokumenta:meta.identifikator_dokumenta,
  nazvanie:String(meta.nazvanie).trim(),
  tip_dokumenta:meta.tip_dokumenta,
  versiya_istochnika:meta.versiya_istochnika ? String(meta.versiya_istochnika).trim() : null,
  data_obnovleniya:meta.data_obnovleniya || null,
  kontrolnye_voprosy:meta.kontrolnye_voprosy.map(q=>({
    vopros:String(q.vopros||'').trim(),
    ozhidaemyy_razdel:String(q.ozhidaemyy_razdel||'').trim(),
    ozhidaemyy_fakt:q.ozhidaemyy_fakt ? String(q.ozhidaemyy_fakt).trim() : null
  }))
};
const canonicalPayload=JSON.stringify({format:'katona_kb_semantic_v1',metadata:canonicalMeta,markdown:body});
const contentHash=sha256Hex(canonicalPayload);
const warnings=[];
if (canonicalMeta.kontrolnye_voprosy.length<3) warnings.push('Для автоматической первой публикации нужны 3–10 контрольных вопросов.');

return [{json:{
  ...base,
  kb01b1_est_zadanie:true,
  kb01b1_valid:true,
  kb01b1_kod:'provereno',
  kb01b1_opisanie:'YAML/Markdown прошёл KB-01B1 validation.',
  kb01b1_metadata:canonicalMeta,
  kb01b1_hash_soderzhaniya:contentHash,
  kb01b1_parser_versiya:String(cfg.parser_versiya||'kb01b1_safe_frontmatter_markdown_v1'),
  kb01b1_zagolovkov:headings.length,
  kb01b1_kontrolnyh_voprosov:canonicalMeta.kontrolnye_voprosy.length,
  kb01b1_markdown_body:body,
  kb01b1_preduprezhdeniya:warnings
}}];

