={{ [
  JSON.stringify({
    operaciya_id:'kb:worker:parse-retry:'+String($json.zadanie_id||'')+':'+String($json.nomer_vladeniya||''),
    zadanie_id:$json.zadanie_id,
    worker_id:$json.vladelec_arendy,
    nomer_vladeniya:$json.nomer_vladeniya,
    status:'povtor',
    sleduyushchiy_zapusk:new Date(Date.now()+Number($json.kb01b1_cfg?.povtor_cherez_sekund||300)*1000).toISOString(),
    kod_oshibki:String($json.kb01b1_kod||'kb01b1_validation_error'),
    opisanie_oshibki:String($json.kb01b1_opisanie||'Ошибка проверки Markdown').slice(0,1000)
  }),
  JSON.stringify({
    valid:$json.kb01b1_valid,
    kod:$json.kb01b1_kod,
    opisanie:$json.kb01b1_opisanie,
