  })
] }}

parameters.jsCode:
return [{json:{
  kb01b1_status:'net_zadaniya',
  rezultat:$json.rezultat||'net_zadaniya',
  opisanie:$json.opisanie||'Ожидающих knowledge jobs сейчас нет.'
}}];

const src = $json || {};
const cfg = src.kb01b1_cfg || {};
const p = cfg.profil || {};

const K=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
const rotr=(x,n)=>(x>>>n)|(x<<(32-n));
function sha256Bytes(bytes){
  const bitLen=bytes.length*8,pad=(64-((bytes.length+1+8)%64))%64;
  const msg=new Uint8Array(bytes.length+1+pad+8);
  msg.set(bytes); msg[bytes.length]=0x80;
  const hi=Math.floor(bitLen/0x100000000),lo=bitLen>>>0,o=msg.length-8;
  msg[o]=(hi>>>24)&255; msg[o+1]=(hi>>>16)&255; msg[o+2]=(hi>>>8)&255; msg[o+3]=hi&255;
  msg[o+4]=(lo>>>24)&255; msg[o+5]=(lo>>>16)&255; msg[o+6]=(lo>>>8)&255; msg[o+7]=lo&255;
  let h=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const w=new Uint32Array(64);
  for(let off=0;off<msg.length;off+=64){
    for(let i=0;i<16;i++){
      const q=off+i*4;
      w[i]=((msg[q]<<24)|(msg[q+1]<<16)|(msg[q+2]<<8)|msg[q+3])>>>0;
    }
    for(let i=16;i<64;i++){
      const a=w[i-15],b=w[i-2];
      const s0=(rotr(a,7)^rotr(a,18)^(a>>>3))>>>0;
      const s1=(rotr(b,17)^rotr(b,19)^(b>>>10))>>>0;
      w[i]=(w[i-16]+s0+w[i-7]+s1)>>>0;
    }
    let [a,b,c,d,e,f,g,hh]=h;
    for(let i=0;i<64;i++){
      const S1=(rotr(e,6)^rotr(e,11)^rotr(e,25))>>>0;
      const ch=((e&f)^((~e)&g))>>>0;
      const t1=(hh+S1+ch+K[i]+w[i])>>>0;
      const S0=(rotr(a,2)^rotr(a,13)^rotr(a,22))>>>0;
