const status=String(r.status_versii||'');
const code=String(r.kod_oshibki||'');
const description=String(r.opisanie||'');

const activeDuplicate=
  result==='dublikat' &&
  status==='opublikovana' &&
  description.includes('Отпечаток совпадает с активной версией');

const preparedDraft=
  (result==='uspeshno' && status==='chernovik') ||
  (result==='dublikat' && status==='chernovik');

const alreadyReleased=
  result==='povtor' ||
  activeDuplicate ||
  code==='stale_lease';

const releaseNeeded=
  preparedDraft ||
  (result==='dublikat' && !activeDuplicate) ||
  (!alreadyReleased && (result==='otkaz' || result==='konflikt'));

return [{
  json:{
    ...r,
    kb01b2_release_needed:releaseNeeded,
    kb01b2_active_duplicate:activeDuplicate,
    kb01b2_prepared_draft:preparedDraft,
    kb01b2_job:{
      zadanie_id:k.zadanie_id,
      worker_id:k.worker_id,
      nomer_vladeniya:k.nomer_vladeniya,
      povtor_cherez_sekund:k.povtor_cherez_sekund||300
    },
    kb01b2_runtime:{
      profil:k.kb01b2_profil,
      otpechatok_profilya:k.kb01b2_otpechatok_profilya,
