function cleanTextSegment(text, report) {
  let out = text;
  out = out.replace(/<!--[\s\S]*?-->/g, () => {
    report.html_comments_removed++;
    return '';
  });
  out = out.replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1\s*>/gi, (m, tag) => {
    report.script_style_removed++;
    report.removed_tags.push(String(tag).toLowerCase());
    return '';
  });
  return out;
}

function cleanOutsideFences(text) {
  const lines = text.split('\n');
  const report = {
    html_comments_removed: 0,
    script_style_removed: 0,
    removed_tags: [],
    warnings: []
  };
  const out = [];
  let textBuffer = [];
  let fence = null;

  const flushText = () => {
    if (!textBuffer.length) return;
    const cleaned = cleanTextSegment(textBuffer.join('\n'), report);
    out.push(...cleaned.split('\n'));
    textBuffer = [];
  };

  for (const line of lines) {
    const fm = line.match(/^\s*(`{3,}|~{3,})/);
    if (!fence && fm) {
      flushText();
      const token = fm[1];
      fence = { ch: token[0], len: token.length };
      out.push(line);
      continue;
    }
    if (fence) {
      out.push(line);
      if (fm && fm[1][0] === fence.ch && fm[1].length >= fence.len) {
        fence = null;
      }
      continue;
    }
    textBuffer.push(line);
  }
  flushText();

  if (fence) report.warnings.push('После очистки обнаружен незакрытый fenced code block.');
  if (/<!--/.test(out.join('\n')) && !/-->/.test(out.join('\n'))) {
    report.warnings.push('Обнаружен незакрытый HTML comment; блок сохранён без догадки.');
  }
  return { text: out.join('\n'), report };
}

function isFenceStart(line) {
  return line.match(/^\s*(`{3,}|~{3,})/);
}
function isListStart(line) {
  return /^\s*(?:[-+*]|\d+[.)])\s+/.test(line);
}
function isTableSeparator(line) {
  const s = line.trim();
  if (!s.includes('|')) return false;
  const core = s.replace(/^\|/,'').replace(/\|$/,'');
  const cells = core.split('|').map(x=>x.trim());
  return cells.length >= 2 && cells.every(c => /^:?-{3,}:?$/.test(c));
