  const a = text.split('\n');
  return Math.max(0, a.length - 2);
}

function parseSection(lines, path, blocks, metaInfo) {
  let i = 0;
  while (i < lines.length) {
    while (i < lines.length && lines[i].trim() === '') i++;
    if (i >= lines.length) break;

    const startFence = isFenceStart(lines[i]);
    if (startFence) {
      const token = startFence[1];
      const ch = token[0], len = token.length;
      const part = [lines[i]];
      i++;
      let closed = false;
      while (i < lines.length) {
        const line = lines[i];
        part.push(line);
        const fm = isFenceStart(line);
        i++;
        if (fm && fm[1][0] === ch && fm[1].length >= len) {
          closed = true;
          break;
        }
      }
      if (!closed) throw new Error('Незакрытый fenced code block после структурной очистки');
      blocks.push(makeBlock('code', part.join('\n'), path, metaInfo));
      continue;
    }

    if (looksLikeTable(lines, i)) {
      const part = [lines[i], lines[i+1]];
      i += 2;
      while (i < lines.length && lines[i].trim() !== '') {
        if (!lines[i].includes('|')) break;
        part.push(lines[i]);
        i++;
      }
      blocks.push(makeBlock('table', part.join('\n'), path, metaInfo, { stroki_tablicy: countTableRows(part.join('\n')) }));
      continue;
    }

    if (isListStart(lines[i])) {
      const part = [lines[i]];
      i++;
      while (i < lines.length && lines[i].trim() !== '') {
        if (looksLikeTable(lines, i) || isFenceStart(lines[i])) break;
        part.push(lines[i]);
        i++;
      }
      blocks.push(makeBlock('list', part.join('\n'), path, metaInfo));
      continue;
    }

    const part = [lines[i]];
    i++;
    while (i < lines.length && lines[i].trim() !== '') {
      if (looksLikeTable(lines, i) || isFenceStart(lines[i]) || isListStart(lines[i])) break;
      part.push(lines[i]);
