    poryadok_bloka: 0,
    tip_bloka: type,
    put_razdela: path.join(' > '),
    uroven_zagolovka: path.length,
    zagolovok_razdela: last,
    faq_razdel: faq,
    tekst: normalized,
    stroki: normalized ? normalized.split('\n').length : 0,
