  for (const line of lines) {
    const fm = line.match(/^\s*(`{3,}|~{3,})/);
    if (fm) {
      const token = fm[1];
      if (!fence) fence = { ch: token[0], len: token.length };
      else if (token[0] === fence.ch && token.length >= fence.len) fence = null;
      sectionLines.push(line);
      continue;
    }

    if (!fence) {
      const hm = line.match(/^(#{1,6})[ \t]+(.+?)\s*#*\s*$/);
