  if (!pathSeen.has(b.put_razdela)) {
    pathSeen.add(b.put_razdela);
    paths.push(b.put_razdela);
  }
}

const structureForHash = blocks.map(b => ({
  poryadok_bloka:b.poryadok_bloka,
  tip_bloka:b.tip_bloka,
  put_razdela:b.put_razdela,
  faq_razdel:b.faq_razdel,
  tekst:b.tekst,
  stroki_tablicy:b.stroki_tablicy ?? null
}));
const structureHash = sha256Hex(JSON.stringify({
  format:'katona_kb_structural_blocks_v1',
  identifikator_dokumenta:String(meta.identifikator_dokumenta||''),
  blocks:structureForHash
}));

const report = {
  versiya:'kb02a1_structural_blocks_v1',
  blokov:blocks.length,
  zagolovkov:headingCount,
  tipy:typeCounts,
  puti_razdelov:paths,
  html_comments_removed:cleanedResult.report.html_comments_removed,
  script_style_removed:cleanedResult.report.script_style_removed,
  warnings:cleanedResult.report.warnings,
  yaml_isklyuchen:true,
  kontrolnye_voprosy_v_retrieval:false,
  token_count_vypolnen:false,
  db_fragmenty_sohraneny:false,
  hash_struktury:structureHash
