execute.code:
const inputItems = this.getInputData();
let splitter;
try {
  splitter = await this.getInputConnectionData('ai_textSplitter', 0);
} catch (e) {
  splitter = null;
}

function failItem(src, code, description, details = {}) {
  const out = { ...src };
  delete out.kb02a1_bloki;
  return {
    json: {
      ...out,
      kb02a2_kandidaty_gotovy: false,
      kb02a2_kod: code,
      kb02a2_opisanie: description,
      kb02a2_detali: details,
      kb02a2_otchet: {
        versiya: 'kb02a2_exact_cl100k_pack_v1',
        tokenizer: 'cl100k_base',
        exact_token_count: false,
        llm_vyzovov: 0,
        embeddings_vyzovov: 0,
        db_fragmenty_sohraneny: false
      }
    }
  };
}

if (!splitter || typeof splitter.splitText !== 'function') {
  return inputItems.map(item => failItem(item.json || {}, 'kb02a2_tokenizer_node_nedostupen', 'Не получен встроенный Token Splitter n8n через ai_textSplitter.'));
}

let tokenizer = null;
let canarySplits = null;
let canaryTokens = null;
let encodingName = null;
try {
  encodingName = String(splitter.encodingName || '');
  canarySplits = await splitter.splitText('hello world');
  tokenizer = splitter.tokenizer;
  if (!tokenizer || typeof tokenizer.encode !== 'function') {
    throw new Error('Встроенный Token Splitter не открыл точный tokenizer; возможен fallback.');
  }
  canaryTokens = tokenizer.encode('hello world', [], []).length;
  if (encodingName !== 'cl100k_base') throw new Error(`Ожидался cl100k_base, получено ${encodingName || '(пусто)'}`);
  if (canaryTokens !== 2) throw new Error(`Canary hello world должен давать 2 токена, получено ${canaryTokens}`);
} catch (e) {
  return inputItems.map(item => failItem(item.json || {}, 'kb02a2_tochnyy_tokenizer_ne_proyden', String(e.message || e), {
    encoding_name: encodingName,
    canary_splits: Array.isArray(canarySplits) ? canarySplits.length : null,
    canary_tokens: canaryTokens,
    tokenizer_object: !!tokenizer
  }));
}

function tokenCount(text) {
  return tokenizer.encode(String(text || ''), [], []).length;
}

const K = [
  0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
  0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
  0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
  0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
  0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
  0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
  0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
  0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
];
const rotr = (x,n) => (x >>> n) | (x << (32-n));
function sha256Bytes(bytes) {
  const bitLen = bytes.length * 8;
  const pad = (64 - ((bytes.length + 1 + 8) % 64)) % 64;
  const msg = new Uint8Array(bytes.length + 1 + pad + 8);
  msg.set(bytes); msg[bytes.length] = 0x80;
  const hi = Math.floor(bitLen / 0x100000000), lo = bitLen >>> 0, o = msg.length - 8;
  msg[o]=(hi>>>24)&255; msg[o+1]=(hi>>>16)&255; msg[o+2]=(hi>>>8)&255; msg[o+3]=hi&255;
  msg[o+4]=(lo>>>24)&255; msg[o+5]=(lo>>>16)&255; msg[o+6]=(lo>>>8)&255; msg[o+7]=lo&255;
  let h=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const w=new Uint32Array(64);
  for(let off=0;off<msg.length;off+=64){
    for(let i=0;i<16;i++){const j=off+i*4;w[i]=((msg[j]<<24)|(msg[j+1]<<16)|(msg[j+2]<<8)|msg[j+3])>>>0;}
    for(let i=16;i<64;i++){const a=w[i-15],b=w[i-2];const s0=(rotr(a,7)^rotr(a,18)^(a>>>3))>>>0;const s1=(rotr(b,17)^rotr(b,19)^(b>>>10))>>>0;w[i]=(w[i-16]+s0+w[i-7]+s1)>>>0;}
    let [a,b,c,d,e,f,g,hh]=h;
    for(let i=0;i<64;i++){const S1=(rotr(e,6)^rotr(e,11)^rotr(e,25))>>>0;const ch=((e&f)^((~e)&g))>>>0;const t1=(hh+S1+ch+K[i]+w[i])>>>0;const S0=(rotr(a,2)^rotr(a,13)^rotr(a,22))>>>0;const maj=((a&b)^(a&c)^(b&c))>>>0;const t2=(S0+maj)>>>0;hh=g;g=f;f=e;e=(d+t1)>>>0;d=c;c=b;b=a;a=(t1+t2)>>>0;}
    h=[(h[0]+a)>>>0,(h[1]+b)>>>0,(h[2]+c)>>>0,(h[3]+d)>>>0,(h[4]+e)>>>0,(h[5]+f)>>>0,(h[6]+g)>>>0,(h[7]+hh)>>>0];
  }
  return h.map(x=>x.toString(16).padStart(8,'0')).join('');
}
function utf8Bytes(text) {
  const s = String(text ?? '');
  const out = [];
  for (let i = 0; i < s.length; i++) {
    let cp = s.charCodeAt(i);
    if (cp >= 0xD800 && cp <= 0xDBFF) {
      if (i + 1 < s.length) {
        const lo = s.charCodeAt(i + 1);
        if (lo >= 0xDC00 && lo <= 0xDFFF) {
          cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
          i++;
        } else {
          cp = 0xFFFD;
        }
      } else {
        cp = 0xFFFD;
      }
    } else if (cp >= 0xDC00 && cp <= 0xDFFF) {
      cp = 0xFFFD;
    }

    if (cp <= 0x7F) {
      out.push(cp);
    } else if (cp <= 0x7FF) {
      out.push(0xC0 | (cp >> 6), 0x80 | (cp & 0x3F));
    } else if (cp <= 0xFFFF) {
      out.push(
        0xE0 | (cp >> 12),
        0x80 | ((cp >> 6) & 0x3F),
        0x80 | (cp & 0x3F)
      );
    } else {
      out.push(
        0xF0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3F),
        0x80 | ((cp >> 6) & 0x3F),
        0x80 | (cp & 0x3F)
      );
    }
  }
  return new Uint8Array(out);
}
const sha256Hex = text => sha256Bytes(utf8Bytes(text));

function normalizeText(text) {
  return String(text || '').replace(/[ \t]+$/gm, '').replace(/^\n+|\n+$/g, '');
}

function renderFinal(title, path, content) {
  return `Документ: ${title}\nРаздел: ${path}\n\n${normalizeText(content)}`;
}

function splitSentences(text) {
  const s = normalizeText(text).trim();
  if (!s) return [];
  const parts = s.split(/(?<=[.!?…])\s+(?=[A-ZА-ЯЁ0-9«"(])/u).map(x => x.trim()).filter(Boolean);
  return parts.length ? parts : [s];
}

function splitSemicolon(text) {
  const parts=[];
  let buf='';
  for (const p of String(text).split(/(?<=;)\s+/u)) {
    const next = buf ? `${buf} ${p}` : p;
    if (!buf) buf=p; else { parts.push(buf.trim()); buf=p; }
  }
  if (buf.trim()) parts.push(buf.trim());
  return parts.length ? parts : [String(text).trim()];
}

function listItems(text) {
  const lines = String(text).split('\n');
  const items=[];
  let cur=[];
  const start = /^\s*(?:[-+*]|\d+[.)])\s+/;
  for (const line of lines) {
    if (start.test(line)) {
      if (cur.length) items.push(cur.join('\n'));
      cur=[line];
    } else if (cur.length) cur.push(line);
    else cur=[line];
  }
  if (cur.length) items.push(cur.join('\n'));
  return items.map(normalizeText).filter(Boolean);
}

function makeAtom(block, text, options={}) {
  return {
    text: normalizeText(text),
    source_blocks: [Number(block.poryadok_bloka)],
    source_type: String(block.tip_bloka),
    split_group: options.split_group || null,
    split_piece: options.split_piece ?? null,
    table_repeat_header: !!options.table_repeat_header,
    overlap_eligible: !!options.overlap_eligible
  };
}

function buildAtomsForBlock(block, title, maxTokens, targetTokens, warnings) {
  const path=String(block.put_razdela || '').trim();
  const full=renderFinal(title,path,block.tekst);
  const fullCount=tokenCount(full);
  if (fullCount <= maxTokens) return [makeAtom(block, block.tekst)];

  const group=`block:${block.poryadok_bloka}`;
  if (block.tip_bloka === 'code') {
    throw new Error(`kb02a2_code_slishkom_dlinniy|Code block ${block.poryadok_bloka} превышает ${maxTokens} токенов и считается неделимым.`);
  }

  if (block.tip_bloka === 'table') {
    const lines=String(block.tekst).split('\n');
    if (lines.length < 3) throw new Error(`kb02a2_tablica_nevalidna|Таблица block ${block.poryadok_bloka} не содержит header/separator/rows.`);
    const header=lines[0], sep=lines[1], rows=lines.slice(2).filter(x=>x.trim()!=='');
    const atoms=[];
    let current=[];
    const finalFor = rs => renderFinal(title,path,[header,sep,...rs].join('\n'));
    for (const row of rows) {
      if (tokenCount(finalFor([row])) > maxTokens) {
        throw new Error(`kb02a2_stroka_tablicy_slishkom_dlinnaya|Строка таблицы block ${block.poryadok_bloka} не помещается в ${maxTokens} токенов даже с повторённым header.`);
      }
      const trial=[...current,row];
      const t=tokenCount(finalFor(trial));
      if (!current.length || t <= targetTokens) {
        current=trial;
      } else {
        atoms.push(makeAtom(block,[header,sep,...current].join('\n'),{split_group:group,split_piece:atoms.length+1,table_repeat_header:true}));
        current=[row];
      }
    }
    if (current.length) atoms.push(makeAtom(block,[header,sep,...current].join('\n'),{split_group:group,split_piece:atoms.length+1,table_repeat_header:true}));
    warnings.push(`table block ${block.poryadok_bloka} разделён по строкам с повторением header`);
    return atoms;
  }

  if (block.tip_bloka === 'list') {
    const items=listItems(block.tekst);
    const atoms=[];
    for (const item of items) {
      const c=tokenCount(renderFinal(title,path,item));
      if (c > maxTokens) {
        throw new Error(`kb02a2_element_spiska_slishkom_dlinniy|Элемент списка block ${block.poryadok_bloka} превышает ${maxTokens} токенов; источник нужно разделить.`);
      }
      atoms.push(makeAtom(block,item,{split_group:group,split_piece:atoms.length+1}));
    }
    warnings.push(`list block ${block.poryadok_bloka} разделён по элементам списка`);
    return atoms;
  }

  const sentences=splitSentences(block.tekst);
  const expanded=[];
  for (const sentence of sentences) {
    if (tokenCount(renderFinal(title,path,sentence)) <= maxTokens) {
      expanded.push(sentence);
      continue;
    }
    const semi=splitSemicolon(sentence);
    if (semi.length === 1) {
      throw new Error(`kb02a2_predlozhenie_slishkom_dlinnoe|Неделимое предложение block ${block.poryadok_bloka} превышает ${maxTokens} токенов; источник нужно разделить.`);
    }
    for (const part of semi) {
      if (tokenCount(renderFinal(title,path,part)) > maxTokens) {
        throw new Error(`kb02a2_predlozhenie_slishkom_dlinnoe|Часть предложения block ${block.poryadok_bloka} превышает ${maxTokens} токенов; источник нужно разделить.`);
      }
      expanded.push(part);
    }
  }
  const atoms=expanded.map((s,i)=>makeAtom(block,s,{split_group:group,split_piece:i+1,overlap_eligible:true}));
  warnings.push(`paragraph block ${block.poryadok_bloka} разделён по предложениям`);
  return atoms;
}

function appendContent(units) {
  return units.map(u=>u.text).join('\n\n');
}

function uniqueNumbers(arr) {
  return [...new Set(arr.map(Number))];
}

function packTopic(title, path, atoms, targetTokens, maxTokens, overlapLimit) {
  const raw=[];
  let current=[];
  const countUnits = units => tokenCount(renderFinal(title,path,appendContent(units)));
  const finalize = () => {
    if (!current.length) return;
    raw.push({units:current.slice()});
    current=[];
  };

  for (const atom of atoms) {
    if (!current.length) { current=[atom]; continue; }
    const currentCount=countUnits(current);
    const combined=[...current,atom];
    const combinedCount=countUnits(combined);
    const shouldCombine = combinedCount <= targetTokens ||
      (currentCount < 80 && combinedCount <= maxTokens) ||
      (combinedCount <= maxTokens && Math.abs(combinedCount-targetTokens) < Math.abs(currentCount-targetTokens));
    if (shouldCombine) current=combined;
    else { finalize(); current=[atom]; }
  }
  finalize();

  const result=[];
  for (let i=0;i<raw.length;i++) {
    let units=raw[i].units.slice();
    let overlapUnits=[];
    let overlapDelta=0;
    if (i>0) {
      const prev=raw[i-1].units;
      const firstGroup=units[0]?.split_group || null;
      const lastGroup=prev[prev.length-1]?.split_group || null;
      const overlapEligible = !!units[0]?.overlap_eligible && !!prev[prev.length-1]?.overlap_eligible;
      if (firstGroup && firstGroup === lastGroup && overlapEligible) {
        const candidates=[];
        for (let j=prev.length-1;j>=0;j--) {
          if (prev[j].split_group !== firstGroup) break;
          candidates.unshift(prev[j]);
          const baseCount=countUnits(units);
          const withCount=countUnits([...candidates,...units]);
          const delta=withCount-baseCount;
          if (delta <= overlapLimit && withCount <= maxTokens) {
            overlapUnits=candidates.slice();
            overlapDelta=delta;
          } else {
            candidates.shift();
            break;
          }
        }
      }
    }
    const finalUnits=[...overlapUnits,...units];
    const text=renderFinal(title,path,appendContent(finalUnits));
    const tokens=tokenCount(text);
    if (tokens > maxTokens) throw new Error(`kb02a2_fragment_prevysil_max|После overlap fragment в разделе «${path}» имеет ${tokens} токенов.`);
    result.push({
      path,
      text,
      tokens,
      overlap_tokens:overlapDelta,
      source_blocks:uniqueNumbers(units.flatMap(u=>u.source_blocks)),
      overlap_source_blocks:uniqueNumbers(overlapUnits.flatMap(u=>u.source_blocks)),
      source_types:[...new Set(units.map(u=>u.source_type))]
    });
  }
  return result;
}

const output=[];
for (const item of inputItems) {
  const src=item.json || {};
  if (src.kb02a1_struktura_gotova !== true || !Array.isArray(src.kb02a1_bloki) || !src.kb02a1_bloki.length) {
    output.push(failItem(src,'kb02a2_net_strukturnyh_blokov','KB-02A2 требует успешно сформированные structural blocks из KB-02A1.'));
    continue;
  }
  const cfg=src.kb01b1_cfg || {};
  const profile=cfg.profil || {};
  const target=Number(profile.cel_fragmenta_tokenov || 600);
  const max=Number(profile.maks_fragmenta_tokenov || 800);
  const overlap=Number(profile.overlap_tokenov || 100);
  const title=String(src.kb01b1_metadata?.nazvanie || '').trim();
  if (!title || target <= 0 || max < target || overlap < 0 || overlap >= target) {
    output.push(failItem(src,'kb02a2_profil_nevaliden','Некорректный title или token budget профиля.',{title,target,max,overlap}));
    continue;
  }

  const warnings=[];
  try {
    const topicGroups=[];
    let group=null;
    for (const block of src.kb02a1_bloki) {
      const path=String(block.put_razdela || '').trim();
      if (!path || !String(block.tekst || '').trim()) throw new Error(`kb02a2_blok_nevaliden|Block ${block.poryadok_bloka} не имеет path/text.`);
      if (!group || group.path !== path) {
        group={path,blocks:[]};
        topicGroups.push(group);
      }
      group.blocks.push(block);
    }

    const final=[];
    let splitBlocks=0;
    for (const topic of topicGroups) {
      const atoms=[];
      for (const block of topic.blocks) {
        const produced=buildAtomsForBlock(block,title,max,target,warnings);
        if (produced.length>1) splitBlocks++;
        atoms.push(...produced);
      }
      final.push(...packTopic(title,topic.path,atoms,target,max,overlap));
    }

    if (!final.length) throw new Error('kb02a2_net_kandidatov|Не сформирован ни один candidate fragment.');
    const candidates=final.map((f,i)=>({
      nomer_kandidata:i+1,
      put_razdela:f.path,
      tekst_fragmenta:f.text,
      kolichestvo_tokenov:f.tokens,
      hash_fragmenta:sha256Hex(f.text),
      overlap_tokenov_fakt:f.overlap_tokens,
      istochniki_blokov:f.source_blocks,
      overlap_istochniki_blokov:f.overlap_source_blocks,
      tipy_blokov:f.source_types
    }));
    const tokenCounts=candidates.map(x=>x.kolichestvo_tokenov);
    const overMax=candidates.filter(x=>x.kolichestvo_tokenov>max);
    if (overMax.length) throw new Error(`kb02a2_est_fragmenty_bolshe_max|${overMax.length} candidate fragments превышают max ${max}.`);
    const fingerprint=sha256Hex(JSON.stringify({
      format:'katona_kb_candidate_fragments_v1',
      profile:{tokenizer:'cl100k_base',target,max,overlap,text_format:'katona_kb_fragment_text_v1'},
      fragments:candidates.map(x=>({n:x.nomer_kandidata,path:x.put_razdela,tokens:x.kolichestvo_tokenov,hash:x.hash_fragmenta,overlap:x.overlap_tokenov_fakt}))
    }));
    const total=tokenCounts.reduce((a,b)=>a+b,0);
    const report={
      versiya:'kb02a2_exact_cl100k_pack_v1',
      text_format:'katona_kb_fragment_text_v1',
      tokenizer:'cl100k_base',
      tokenizer_istochnik:'n8n_builtin_TokenTextSplitter_local_encoding',
      exact_token_count:true,
      tokenizer_canary:{text:'hello world',tokens:canaryTokens,encoding:encodingName,tokenizer_object:true},
      target_tokenov:target,
      max_tokenov:max,
      overlap_limit_tokenov:overlap,
      structural_blocks:src.kb02a1_bloki.length,
      topic_groups:topicGroups.length,
      split_source_blocks:splitBlocks,
      kandidatov:candidates.length,
      tokeny_min:Math.min(...tokenCounts),
      tokeny_max:Math.max(...tokenCounts),
      tokeny_srednee:Number((total/candidates.length).toFixed(1)),
      korotkih_do_80:candidates.filter(x=>x.kolichestvo_tokenov<80).length,
      s_overlap:candidates.filter(x=>x.overlap_tokenov_fakt>0).length,
      max_overlap_fakt:candidates.reduce((m,x)=>Math.max(m,x.overlap_tokenov_fakt),0),
      prevyshenie_max:0,
      warnings,
      hash_kandidatov:fingerprint,
      llm_vyzovov:0,
      embeddings_vyzovov:0,
      db_fragmenty_sohraneny:false
    };

    const out={...src};
    delete out.kb02a1_bloki;
    output.push({json:{
      ...out,
      kb02a2_kandidaty_gotovy:true,
      kb02a2_kod:'kandidaty_sformirovany',
      kb02a2_opisanie:'Точный cl100k_base count подтверждён встроенным tokenizer n8n; structural blocks упакованы в final candidate fragments без LLM/embeddings/DB save.',
      kb02a2_fragmenty:candidates,
      kb02a2_otchet:report
    }});
  } catch (e) {
    const msg=String(e.message || e);
    const sep=msg.indexOf('|');
    const code=sep>0?msg.slice(0,sep):'kb02a2_upakovka_oshibka';
    const description=sep>0?msg.slice(sep+1):msg;
    output.push(failItem(src,code,description,{warnings}));
  }
}
return output;

parameters.jsCode:
const src=$json||{};
const records=Array.isArray(src.kb02b_fragmenty)?src.kb02b_fragmenty:[];
const idx=[];
for(let i=0;i<Math.min(2,records.length);i++) idx.push(i);
for(let i=Math.max(0,records.length-2);i<records.length;i++) if(!idx.includes(i)) idx.push(i);
const samples=idx.map(i=>{
  const f=records[i]||{};
  return {
    nomer_fragmenta:f.nomer_fragmenta,
    put_razdela:f.put_razdela,
    kolichestvo_tokenov:f.kolichestvo_tokenov,
    hash_fragmenta:f.hash_fragmenta,
    trace:f.trace,
    preview:String(f.tekst_fragmenta||'').slice(0,500)
  };
});
const q=Array.isArray(src.kb02b_kontrolnye_voprosy)?src.kb02b_kontrolnye_voprosy:[];
const out={
  ...src,
  kb02b_samples_fragmentov:samples,
  kb02b_voprosy_summary:{
    kolichestvo:q.length,
    nomera:q.map(x=>x.nomer),
    istochnik:'yaml',
    gotovy_dlya_avtoproverki:src.kb02b_kontrolnye_gotovy===true,
    v_retrieval_text:false,
    hash_nabora:src.kb02b_otchet?.hash_nabora_kontrolnyh_voprosov||null
  }
};
delete out.kb02a2_fragmenty;
if(out.kb02a1_otchet){
  const a=out.kb02a1_otchet;
  out.kb02a1_otchet={
    versiya:a.versiya,blokov:a.blokov,zagolovkov:a.zagolovkov,tipy:a.tipy,
    warnings:a.warnings,hash_struktury:a.hash_struktury,
    yaml_isklyuchen:a.yaml_isklyuchen,
    kontrolnye_voprosy_v_retrieval:a.kontrolnye_voprosy_v_retrieval
  };
}
if(out.kb01b1_metadata){
  const m=out.kb01b1_metadata;
  out.kb01b1_metadata={
    identifikator_dokumenta:m.identifikator_dokumenta,nazvanie:m.nazvanie,tip_dokumenta:m.tip_dokumenta,
    versiya_istochnika:m.versiya_istochnika,data_obnovleniya:m.data_obnovleniya,
    kontrolnyh_voprosov:q.length
  };
}
return [{json:out}];

