const K = [
  0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
  0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
  0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
  0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
  0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
  0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
  0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
  0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
];
const rotr = (x,n) => (x >>> n) | (x << (32-n));
function sha256Bytes(bytes) {
  const bitLen = bytes.length * 8;
  const pad = (64 - ((bytes.length + 1 + 8) % 64)) % 64;
  const msg = new Uint8Array(bytes.length + 1 + pad + 8);
  msg.set(bytes); msg[bytes.length] = 0x80;
  const hi = Math.floor(bitLen / 0x100000000), lo = bitLen >>> 0, o = msg.length - 8;
  msg[o]=(hi>>>24)&255; msg[o+1]=(hi>>>16)&255; msg[o+2]=(hi>>>8)&255; msg[o+3]=hi&255;
  msg[o+4]=(lo>>>24)&255; msg[o+5]=(lo>>>16)&255; msg[o+6]=(lo>>>8)&255; msg[o+7]=lo&255;
  let h=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const w=new Uint32Array(64);
  for(let off=0;off<msg.length;off+=64){
    for(let i=0;i<16;i++){const j=off+i*4;w[i]=((msg[j]<<24)|(msg[j+1]<<16)|(msg[j+2]<<8)|msg[j+3])>>>0;}
    for(let i=16;i<64;i++){const a=w[i-15],b=w[i-2];const s0=(rotr(a,7)^rotr(a,18)^(a>>>3))>>>0;const s1=(rotr(b,17)^rotr(b,19)^(b>>>10))>>>0;w[i]=(w[i-16]+s0+w[i-7]+s1)>>>0;}
    let [a,b,c,d,e,f,g,hh]=h;
    for(let i=0;i<64;i++){const S1=(rotr(e,6)^rotr(e,11)^rotr(e,25))>>>0;const ch=((e&f)^((~e)&g))>>>0;const t1=(hh+S1+ch+K[i]+w[i])>>>0;const S0=(rotr(a,2)^rotr(a,13)^rotr(a,22))>>>0;const maj=((a&b)^(a&c)^(b&c))>>>0;const t2=(S0+maj)>>>0;hh=g;g=f;f=e;e=(d+t1)>>>0;d=c;c=b;b=a;a=(t1+t2)>>>0;}
    h=[(h[0]+a)>>>0,(h[1]+b)>>>0,(h[2]+c)>>>0,(h[3]+d)>>>0,(h[4]+e)>>>0,(h[5]+f)>>>0,(h[6]+g)>>>0,(h[7]+hh)>>>0];
  }
  return h.map(x=>x.toString(16).padStart(8,'0')).join('');
}
function utf8Bytes(text) {
  const s = String(text ?? '');
  const out = [];
  for (let i = 0; i < s.length; i++) {
    let cp = s.charCodeAt(i);
    if (cp >= 0xD800 && cp <= 0xDBFF) {
      if (i + 1 < s.length) {
        const lo = s.charCodeAt(i + 1);
        if (lo >= 0xDC00 && lo <= 0xDFFF) {
          cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
          i++;
        } else cp = 0xFFFD;
      } else cp = 0xFFFD;
    } else if (cp >= 0xDC00 && cp <= 0xDFFF) cp = 0xFFFD;
    if (cp <= 0x7F) out.push(cp);
    else if (cp <= 0x7FF) out.push(0xC0 | (cp >> 6), 0x80 | (cp & 0x3F));
    else if (cp <= 0xFFFF) out.push(0xE0 | (cp >> 12),0x80 | ((cp >> 6) & 0x3F),0x80 | (cp & 0x3F));
    else out.push(0xF0 | (cp >> 18),0x80 | ((cp >> 12) & 0x3F),0x80 | ((cp >> 6) & 0x3F),0x80 | (cp & 0x3F));
  }
  return new Uint8Array(out);
}
const sha256Hex = text => sha256Bytes(utf8Bytes(text));

const src = $json || {};
const frags = Array.isArray(src.kb02a2_fragmenty) ? src.kb02a2_fragmenty : [];
const meta = src.kb01b1_metadata || {};
const qs = Array.isArray(meta.kontrolnye_voprosy) ? meta.kontrolnye_voprosy : [];
const profile = src.kb01b2_profil || src.kb01b1_cfg?.profil || {};
const maxTokens = Number(profile.maks_fragmenta_tokenov || 800);
const targetTokens = Number(profile.cel_fragmenta_tokenov || 600);
const overlapLimit = Number(profile.overlap_tokenov || 100);

function fail(code, description, details={}) {
  const out={...src};
  delete out.kb02a2_fragmenty;
  delete out.kb02b_fragmenty;
  delete out.kb02b_kontrolnye_voprosy;
  return [{json:{
    ...out,
    kb02b_zapisi_gotovy:false,
    kb02b_kontrolnye_gotovy:false,
    kb02b_kod:code,
    kb02b_opisanie:description,
    kb02b_detali:details,
    kb02b_otchet:{
      versiya:'kb02b_fragment_records_v1',
      fragmentov:frags.length,
      kontrolnyh_voprosov:qs.length,
      llm_vyzovov:0,
      embeddings_vyzovov:0,
      db_fragmenty_sohraneny:false,
      db_kontrolnye_sohraneny:false
    }
  }}];
}

if (src.kb02a2_kandidaty_gotovy !== true || src.kb02a2_otchet?.exact_token_count !== true || !frags.length) {
  return fail('kb02b_net_gotovyh_kandidatov','KB-02B требует успешно сформированные A2 candidates с exact token count.');
}
if (!Number.isInteger(maxTokens) || maxTokens <= 0) {
  return fail('kb02b_profil_nevaliden','Не найден корректный maks_fragmenta_tokenov.');
}

const records=[];
for (let i=0;i<frags.length;i++) {
  const f=frags[i] || {};
  const n=Number(f.nomer_kandidata);
  const path=String(f.put_razdela||'').trim();
  const text=String(f.tekst_fragmenta||'');
  const tokens=Number(f.kolichestvo_tokenov);
  const hash=String(f.hash_fragmenta||'').toLowerCase();
  if (!Number.isInteger(n) || n !== i+1) {
    return fail('kb02b_narushen_poryadok',`Candidate ${i+1} имеет нестабильный номер.`,{index:i+1,nomer_kandidata:f.nomer_kandidata});
  }
  if (!path || !text.trim()) {
    return fail('kb02b_pustoy_fragment',`Fragment ${n} требует непустой path/text.`);
  }
  if (!Number.isInteger(tokens) || tokens <= 0 || tokens > maxTokens) {
    return fail('kb02b_tokeny_nevalidny',`Fragment ${n} имеет недопустимое число токенов.`,{tokens,maxTokens});
  }
  if (!/^[0-9a-f]{64}$/.test(hash)) {
    return fail('kb02b_hash_format',`Fragment ${n} имеет некорректный hash_fragmenta.`);
  }
  const recomputed=sha256Hex(text);
  if (recomputed !== hash) {
    return fail('kb02b_hash_ne_sovpadaet',`Fragment ${n}: hash_fragmenta не соответствует точному tekst_fragmenta.`,{ozhidaetsya:recomputed,polucheno:hash});
  }

  const sourceBlocks=Array.isArray(f.istochniki_blokov)?f.istochniki_blokov.map(Number):[];
  const overlapBlocks=Array.isArray(f.overlap_istochniki_blokov)?f.overlap_istochniki_blokov.map(Number):[];
  const sourceTypes=Array.isArray(f.tipy_blokov)?f.tipy_blokov.map(x=>String(x)):[];
  const validBlocks=a=>a.every(x=>Number.isInteger(x)&&x>0)&&new Set(a).size===a.length;
  if (!sourceBlocks.length || !validBlocks(sourceBlocks) || !validBlocks(overlapBlocks)) {
    return fail('kb02b_trace_nevaliden',`Fragment ${n} имеет некорректный trace source blocks.`);
  }

  records.push({
    nomer_fragmenta:n,
    put_razdela:path,
    tekst_fragmenta:text,
    kolichestvo_tokenov:tokens,
    hash_fragmenta:hash,
    trace:{
      istochniki_blokov:sourceBlocks,
      overlap_istochniki_blokov:overlapBlocks,
      tipy_blokov:sourceTypes,
      overlap_tokenov_fakt:Number(f.overlap_tokenov_fakt||0)
    }
  });
}

const a2Fingerprint=sha256Hex(JSON.stringify({
  format:'katona_kb_candidate_fragments_v1',
  profile:{
    tokenizer:'cl100k_base',
    target:targetTokens,
    max:maxTokens,
    overlap:overlapLimit,
    text_format:'katona_kb_fragment_text_v1'
  },
  fragments:frags.map(f=>({
    n:Number(f.nomer_kandidata),
    path:String(f.put_razdela||'').trim(),
    tokens:Number(f.kolichestvo_tokenov),
    hash:String(f.hash_fragmenta||'').toLowerCase(),
    overlap:Number(f.overlap_tokenov_fakt||0)
  }))
}));
if (String(src.kb02a2_otchet?.hash_kandidatov||'').toLowerCase() !== a2Fingerprint) {
  return fail('kb02b_a2_fingerprint_ne_sovpadaet','A2 candidate fingerprint изменился между packing и KB-02B.',{
    raschet:a2Fingerprint,
    ozhidaetsya:src.kb02a2_otchet?.hash_kandidatov||null
  });
}

const questions=[];
for(let i=0;i<qs.length;i++){
  const q=qs[i]||{};
  const vopros=String(q.vopros||'').trim();
  const razdel=String(q.ozhidaemyy_razdel||'').trim();
  const fakt=q.ozhidaemyy_fakt===null||q.ozhidaemyy_fakt===undefined||String(q.ozhidaemyy_fakt).trim()===''?null:String(q.ozhidaemyy_fakt).trim();
  if(!vopros || !razdel){
    return fail('kb02b_vopros_nevaliden',`Контрольный вопрос ${i+1} не имеет vopros/ozhidaemyy_razdel.`);
  }
  questions.push({
    nomer:i+1,
    vopros,
    ozhidaemyy_razdel:razdel,
    ozhidaemyy_fakt:fakt,
    istochnik:'yaml'
  });
}
if (questions.length > 10) {
  return fail('kb02b_slishkom_mnogo_voprosov','Контрольных вопросов больше 10.',{kolichestvo:questions.length});
}
const questionsReady=questions.length>=3 && questions.length<=10;

const fragmentSetHash=sha256Hex(JSON.stringify({
  format:'katona_kb_fragment_records_v1',
  text_format:'katona_kb_fragment_text_v1',
  fragments:records.map(r=>({
    nomer_fragmenta:r.nomer_fragmenta,
    put_razdela:r.put_razdela,
    kolichestvo_tokenov:r.kolichestvo_tokenov,
    hash_fragmenta:r.hash_fragmenta,
    trace:r.trace
  }))
}));
const questionSetHash=sha256Hex(JSON.stringify({
  format:'katona_kb_reference_questions_v1',
  questions
}));
const readySetHash=sha256Hex(JSON.stringify({
  format:'katona_kb02b_ready_v1',
  otpechatok_obrabotki:String(src.kb01b2_otpechatok_obrabotki||''),
  otpechatok_profilya:String(src.kb01b2_otpechatok_profilya||''),
  hash_fragmentov:fragmentSetHash,
  hash_kontrolnyh_voprosov:questionSetHash
}));

const tokenCounts=records.map(r=>r.kolichestvo_tokenov);
const total=tokenCounts.reduce((a,b)=>a+b,0);
const report={
  versiya:'kb02b_fragment_records_v1',
  text_format:'katona_kb_fragment_text_v1',
  fragmentov:records.length,
  nomera_posledovatelny:true,
  tokeny_min:Math.min(...tokenCounts),
  tokeny_max:Math.max(...tokenCounts),
  tokeny_srednee:Number((total/records.length).toFixed(1)),
  prevyshenie_max:records.filter(r=>r.kolichestvo_tokenov>maxTokens).length,
  hash_a2_kandidatov:a2Fingerprint,
  hash_nabora_fragmentov:fragmentSetHash,
  trace_sohranen_v_runtime:true,
  db_batch_limit:100,
  db_paketov_budushchih:Math.ceil(records.length/100),
  kontrolnyh_voprosov:questions.length,
  kontrolnye_gotovy_dlya_avtoproverki:questionsReady,
  kontrolnye_istochnik:'yaml',
  kontrolnye_v_retrieval_text:false,
  hash_nabora_kontrolnyh_voprosov:questionSetHash,
  hash_gotovogo_nabora:readySetHash,
  llm_vyzovov:0,
  embeddings_vyzovov:0,
  db_fragmenty_sohraneny:false,
  db_kontrolnye_sohraneny:false,
  publish_vypolnen:false
};

return [{json:{
  ...src,
  kb02b_zapisi_gotovy:true,
  kb02b_kontrolnye_gotovy:questionsReady,
  kb02b_kod:questionsReady?'zapisi_i_voprosy_gotovy':'zapisi_gotovy_nuzhny_kontrolnye_voprosy',
  kb02b_opisanie:questionsReady
    ?'Final fragment records и отдельные YAML reference questions подготовлены без embeddings/DB save.'
    :'Final fragment records подготовлены, но для автоматической проверки нужны 3–10 YAML reference questions.',
  kb02b_fragmenty:records,
  kb02b_kontrolnye_voprosy:questions,
  kb02b_otchet:report
}}];

