parameters.jsCode:
const r=$json||{};
const k=r.kb01b2_kontekst||{};
const result=String(r.rezultat||'');
const status=String(r.status_versii||'');
const records=Array.isArray(k.kb02b_fragmenty)?k.kb02b_fragmenty:[];
const cfg=k.kb03a_cfg||{};
const preparedDraft=((result==='uspeshno'||result==='dublikat') && status==='chernovik');
const profile=k.kb01b2_profil||{};
const model=String(cfg.embedding_model||profile.embedding_model||'');
const dim=Number(cfg.dimensions||profile.razmernost||0);
const encoding=String(cfg.encoding_format||'');
const maxBatch=Number(cfg.max_batch_fragmentov||100);
const maxTotalTokens=Number(cfg.max_batch_tokenov_openai||300000);
let code='gotovo_k_embedding';
let description='Draft version и fragment records готовы к OpenAI embeddings.';
let ok=preparedDraft;
if(ok && (!records.length || records.length>maxBatch)){
  ok=false; code='kb03a_batch_razmer'; description='Embedding batch должен содержать 1..100 final fragments.';
}
if(ok && (model!=='text-embedding-3-large'||dim!==1024||encoding!=='float')){
  ok=false; code='kb03a_embedding_profil'; description='KB-03A разрешает только text-embedding-3-large / 1024 / float.';
}
const totalTokens=records.reduce((s,x)=>s+Number(x?.kolichestvo_tokenov||0),0);
if(ok && (!Number.isFinite(totalTokens)||totalTokens<=0||totalTokens>maxTotalTokens)){
  ok=false; code='kb03a_batch_tokeny'; description='Суммарный token budget embedding batch некорректен.';
}
if(ok && records.some((x,i)=>
  Number(x?.nomer_fragmenta)!==i+1 ||
  !String(x?.tekst_fragmenta||'').trim() ||
  !String(x?.put_razdela||'').trim() ||
  !/^[0-9a-f]{64}$/.test(String(x?.hash_fragmenta||'')) ||
  !Number.isInteger(Number(x?.kolichestvo_tokenov)) ||
  Number(x?.kolichestvo_tokenov)<=0 ||
  Number(x?.kolichestvo_tokenov)>800
)){
  ok=false; code='kb03a_fragment_records'; description='Final fragment records не прошли preflight перед embedding.';
}
return [{json:{
  ...r,
  kb03a_prepare_draft:preparedDraft,
  kb03a_mozhno_embedding:ok,
  kb03a_kod:ok?'gotovo_k_embedding':code,
  kb03a_opisanie:ok?description:description,
  kb03a_fragmenty:ok?records:[],
  kb03a_kontrolnye_voprosy:Array.isArray(k.kb02b_kontrolnye_voprosy)?k.kb02b_kontrolnye_voprosy:[],
  kb03b_cfg:k.kb03b_cfg||{},
  kb03a_zapros:{
    model,
    dimensions:dim,
    encoding_format:encoding,
    fragmentov:records.length,
    total_tokens:totalTokens
  },
  kb03a_job:{
    zadanie_id:k.zadanie_id,
    worker_id:k.worker_id,
    nomer_vladeniya:k.nomer_vladeniya,
    povtor_cherez_sekund:Number(k.povtor_cherez_sekund||300)
  },
  kb03a_version:{
    dokument_id:r.dokument_id,
    versiya_id:r.versiya_id,
    nomer_versii:r.nomer_versii,
    profil_indeksa_id:r.profil_indeksa_id,
    status_versii:r.status_versii
  },
  kb03a_report_base:{
    kb02b_hash_nabora_fragmentov:k.kb02b_otchet?.hash_nabora_fragmentov||null,
    kb02b_hash_gotovogo_nabora:k.kb02b_otchet?.hash_gotovogo_nabora||null,
    reference_questions_saved:false,
    publish_vypolnen:false
  }
}}];

const src=$json||{};
const records=Array.isArray(src.kb03a_fragmenty)?src.kb03a_fragmenty:[];
function fail(code,description,details={}){
  const out={...src};
  delete out.data;
  delete out.kb03a_fragmenty_s_vektorom;
  return [{json:{...out,kb03a_embeddings_validny:false,kb03a_kod:code,kb03a_opisanie:description,kb03a_detali:details,
    kb03a_otchet:{fragmentov_ozhidalos:records.length,embedding_api_vyzovov:1,llm_vyzovov:0,db_fragmenty_sohraneny:false,publish_vypolnen:false}}}];
}
if(!records.length) return fail('kb03a_net_fragmentov','Нет final fragment records после merge.');
if(src.error || src.statusCode>=400){
  return fail('kb03a_openai_error','OpenAI embeddings request завершился ошибкой.',{error:src.error||null,statusCode:src.statusCode||null,message:src.message||null});
}
const data=Array.isArray(src.data)?src.data:null;
if(!data) return fail('kb03a_openai_format','Ответ OpenAI не содержит data[].');
if(String(src.model||'')!=='text-embedding-3-large'){
  return fail('kb03a_model_otveta','OpenAI вернул неожидаемую embedding model.',{model:src.model||null});
}
if(data.length!==records.length){
  return fail('kb03a_count_mismatch','Количество embeddings не совпадает с количеством fragments.',{fragmentov:records.length,embeddings:data.length});
}
const byIndex=new Map();
for(const item of data){
  const idx=Number(item?.index);
  const vec=item?.embedding;
  if(!Number.isInteger(idx)||idx<0||idx>=records.length||byIndex.has(idx)){
    return fail('kb03a_index_mismatch','OpenAI data[].index не образует уникальное соответствие fragments.',{index:item?.index});
  }
  if(!Array.isArray(vec)||vec.length!==1024){
    return fail('kb03a_vector_dimension','Embedding vector должен иметь ровно 1024 элемента.',{index:idx,dimension:Array.isArray(vec)?vec.length:null});
  }
  for(let j=0;j<vec.length;j++){
    if(typeof vec[j]!=='number'||!Number.isFinite(vec[j])){
      return fail('kb03a_vector_number','Embedding содержит нечисловое/неконечное значение.',{index:idx,vector_index:j,value:vec[j]});
    }
  }
  byIndex.set(idx,vec);
}
for(let i=0;i<records.length;i++) if(!byIndex.has(i)) return fail('kb03a_index_gap','В ответе OpenAI отсутствует embedding index.',{index:i});

const payload=records.map((f,i)=>({
  nomer_fragmenta:Number(f.nomer_fragmenta),
  put_razdela:String(f.put_razdela),
  tekst_fragmenta:String(f.tekst_fragmenta),
  kolichestvo_tokenov:Number(f.kolichestvo_tokenov),
  hash_fragmenta:String(f.hash_fragmenta),
  vektor:byIndex.get(i)
}));
const dims=payload.map(x=>x.vektor.length);
const usage=src.usage||{};
const out={...src};
delete out.data;
delete out.object;
delete out.model;
delete out.usage;
out.kb03a_embeddings_validny=true;
out.kb03a_kod='embeddings_validny';
out.kb03a_opisanie='OpenAI вернул по одному валидному vector(1024) для каждого exact fragment.';
out.kb03a_fragmenty_s_vektorom=payload;
out.kb03a_otchet={
  model:'text-embedding-3-large',
  dimensions:1024,
  encoding_format:'float',
  fragmentov:records.length,
  vectors:payload.length,
  vector_dim_min:Math.min(...dims),
  vector_dim_max:Math.max(...dims),
  vse_znacheniya_finite:true,
  sopostavlenie_po_index:true,
  input_exact_fragment_text:true,
  request_batches:1,
  usage_prompt_tokens:Number(usage.prompt_tokens||0),
  usage_total_tokens:Number(usage.total_tokens||0),
  embedding_api_vyzovov:1,
  llm_vyzovov:0,
  reference_questions_embedded:false,
  db_fragmenty_sohraneny:false,
  publish_vypolnen:false
};
return [{json:out}];

