const items=$input.all().map(i=>i.json||{});
const first=items[0]||{};
const k=first.kb03b_kontekst||{};
function fail(code,description,details={}){
  return [{json:{
    kb03b_id_gotovy:false,kb03b_kod:code,kb03b_opisanie:description,kb03b_detali:details,
    kb03b_job:{zadanie_id:k.zadanie_id,worker_id:k.worker_id,nomer_vladeniya:k.nomer_vladeniya,povtor_cherez_sekund:Number(k.povtor_cherez_sekund||300)},
    kb03b_version:{dokument_id:k.dokument_id,versiya_id:k.versiya_id,profil_indeksa_id:k.profil_indeksa_id,status_versii:k.status_versii},
    kb03b_cfg:k.cfg||{},kb03b_report:k.report||{},publish_vypolnen:false
  }}];
}
if(!items.length) return fail('kb03b_net_voprosov_id','Bridge не вернул контрольные вопросы.');
if(items.some(x=>String(x.rezultat||'')!=='uspeshno')){
  const bad=items.find(x=>String(x.rezultat||'')!=='uspeshno')||{};
  return fail(String(bad.kod_oshibki||'kb03b_bridge_error'),String(bad.opisanie||'Bridge не подтвердил вопросы.'),{rezultat:bad.rezultat||null});
}
const original=Array.isArray(k.original_voprosy)?k.original_voprosy:[];
const expected=Number(k.expected_voprosov||0);
if(items.length!==expected || original.length!==expected || expected<3 || expected>10){
  return fail('kb03b_count_question_ids','Количество вопросов/ID не совпадает.',{bridge:items.length,original:original.length,expected});
}
const ids=new Set();
const qs=[];
for(let i=0;i<items.length;i++){
  const x=items[i], o=original[i]||{};
  const id=String(x.vopros_id||'');
  const nom=Number(x.nomer);
  if(!/^[0-9a-f-]{36}$/i.test(id)||ids.has(id)||nom!==i+1){
    return fail('kb03b_question_id_order','Question IDs/номера не образуют однозначный порядок.',{index:i+1,vopros_id:id,nomer:x.nomer});
  }
  ids.add(id);
  const vopros=String(x.vopros||'').trim();
  const razdel=String(x.ozhidaemyy_razdel||'').trim();
  const fakt=x.ozhidaemyy_fakt===null||x.ozhidaemyy_fakt===undefined?null:String(x.ozhidaemyy_fakt).trim();
  if(vopros!==String(o.vopros||'').trim() || razdel!==String(o.ozhidaemyy_razdel||'').trim() ||
     (fakt||null)!==(o.ozhidaemyy_fakt===null||o.ozhidaemyy_fakt===undefined?null:String(o.ozhidaemyy_fakt).trim())){
    return fail('kb03b_question_content_mismatch','Bridge question не совпал с canonical YAML набором.',{nomer:nom});
  }
  qs.push({vopros_id:id,nomer:nom,vopros,ozhidaemyy_razdel:razdel,ozhidaemyy_fakt:fakt||null,istochnik:String(x.istochnik||'yaml')});
}
const cfg=k.cfg||{};
if(String(cfg.embedding_model||'')!=='text-embedding-3-large'||Number(cfg.dimensions)!==1024||String(cfg.encoding_format||'')!=='float'){
  return fail('kb03b_embedding_profile','Question embedding profile должен быть text-embedding-3-large / 1024 / float.');
}
return [{json:{
  kb03b_id_gotovy:true,kb03b_kod:'question_ids_gotovy',kb03b_opisanie:`Получены ${qs.length} question IDs под текущим live fence.`,
  kb03b_voprosy_s_id:qs,
  kb03b_job:{zadanie_id:k.zadanie_id,worker_id:k.worker_id,nomer_vladeniya:k.nomer_vladeniya,povtor_cherez_sekund:Number(k.povtor_cherez_sekund||300)},
  kb03b_version:{dokument_id:k.dokument_id,versiya_id:k.versiya_id,profil_indeksa_id:k.profil_indeksa_id,status_versii:k.status_versii},
  kb03b_cfg:cfg,kb03b_report:{...(k.report||{}),question_ids:qs.length,question_ids_unique:true,publish_vypolnen:false}
}}];

const src=$json||{};
const qs=Array.isArray(src.kb03b_voprosy_s_id)?src.kb03b_voprosy_s_id:[];
function fail(code,description,details={}){
  const out={...src}; delete out.data; delete out.object; delete out.model; delete out.usage;
  return [{json:{...out,kb03b_embeddings_validny:false,kb03b_kod:code,kb03b_opisanie:description,kb03b_detali:details,
    kb03b_embedding_otchet:{voprosov_ozhidalos:qs.length,embedding_api_vyzovov:1,generative_llm_vyzovov:0,publish_vypolnen:false}}}];
}
if(qs.length<3||qs.length>10) return fail('kb03b_question_count','Для question embeddings требуется 3..10 вопросов.');
if(src.error || Number(src.statusCode)>=400) return fail('kb03b_openai_error','OpenAI question embeddings завершились ошибкой.',{error:src.error||null,statusCode:src.statusCode||null,message:src.message||null});
const data=Array.isArray(src.data)?src.data:null;
if(!data) return fail('kb03b_openai_format','Ответ OpenAI не содержит data[].');
if(String(src.model||'')!=='text-embedding-3-large') return fail('kb03b_model_response','OpenAI вернул неожиданную embedding model.',{model:src.model||null});
if(data.length!==qs.length) return fail('kb03b_embedding_count','Количество question embeddings не совпало.',{questions:qs.length,embeddings:data.length});
const byIndex=new Map();
for(const x of data){
  const idx=Number(x?.index), vec=x?.embedding;
  if(!Number.isInteger(idx)||idx<0||idx>=qs.length||byIndex.has(idx)) return fail('kb03b_embedding_index','Question embedding index некорректен.',{index:x?.index});
  if(!Array.isArray(vec)||vec.length!==1024) return fail('kb03b_embedding_dim','Question vector должен иметь 1024 элемента.',{index:idx,dim:Array.isArray(vec)?vec.length:null});
  if(vec.some(v=>typeof v!=='number'||!Number.isFinite(v))) return fail('kb03b_embedding_value','Question vector содержит нечисловое/неконечное значение.',{index:idx});
  byIndex.set(idx,vec);
}
for(let i=0;i<qs.length;i++) if(!byIndex.has(i)) return fail('kb03b_embedding_gap','Отсутствует question embedding index.',{index:i});
const withVec=qs.map((q,i)=>({...q,vektor:byIndex.get(i)}));
const usage=src.usage||{};
const out={...src}; delete out.data; delete out.object; delete out.model; delete out.usage;
out.kb03b_embeddings_validny=true;
out.kb03b_voprosy_s_vektorom=withVec;
out.kb03b_kod='question_embeddings_validny';
out.kb03b_opisanie=`Получено ${withVec.length} валидных question vectors(1024).`;
out.kb03b_embedding_otchet={
  model:'text-embedding-3-large',dimensions:1024,encoding_format:'float',
  questions:withVec.length,vectors:withVec.length,vector_dim_min:1024,vector_dim_max:1024,
  vse_znacheniya_finite:true,sopostavlenie_po_index:true,input_exact_question_text:true,
  request_batches:1,usage_prompt_tokens:Number(usage.prompt_tokens||0),usage_total_tokens:Number(usage.total_tokens||0),
  embedding_api_vyzovov:1,generative_llm_vyzovov:0,publish_vypolnen:false
};
return [{json:out}];

const rows=$input.all().map(i=>i.json||{});
const first=rows[0]||{};
const k=first.kb03b_kontekst||{};
function fail(code,description,details={}){
  return [{json:{
    kb03b_ocenka_validna:false,kb03b_kod:code,kb03b_opisanie:description,kb03b_detali:details,
    kb03b_job:{zadanie_id:k.zadanie_id,worker_id:k.worker_id,nomer_vladeniya:k.nomer_vladeniya,povtor_cherez_sekund:Number(k.povtor_cherez_sekund||300)},
    kb03b_version:{dokument_id:k.dokument_id,versiya_id:k.versiya_id,profil_indeksa_id:k.profil_indeksa_id,status_versii:k.status_versii},
    publish_vypolnen:false
  }}];
}
if(!rows.length) return fail('kb03b_search_empty_output','Draft search не вернул даже question rows.');
const topK=Number(k.cfg?.search_top_k||12);
const thresholds=Array.isArray(k.cfg?.calibration_thresholds)?k.cfg.calibration_thresholds.map(Number):[0.45,0.50,0.55,0.60,0.65,0.70,0.75,0.80,0.85];
if(topK!==12 || thresholds.length!==9 || thresholds.some((x,i)=>!Number.isFinite(x)||x<0||x>1||(i&&x<=thresholds[i-1]))){
  return fail('kb03b_calibration_config','KB-03B calibration config некорректен.',{topK,thresholds});
}
const canon=s=>String(s??'').normalize('NFKC').toLowerCase().replace(/ё/g,'е').replace(/[^\p{L}\p{N}]+/gu,' ').replace(/\s+/g,' ').trim();
const groups=new Map();
for(const row of rows){
  const qid=String(row.vopros_id||'');
  if(!qid) return fail('kb03b_search_question_id','Draft search row потерял vopros_id.');
  if(row.poisk_rezultat && String(row.poisk_rezultat)!=='uspeshno'){
    return fail(String(row.poisk_kod_oshibki||'kb03b_search_db_error'),String(row.poisk_opisanie||'Draft search DB отказал.'),{vopros_id:qid});
  }
  if(!groups.has(qid)) groups.set(qid,{vopros_id:qid,nomer:Number(row.nomer),vopros:String(row.vopros||''),ozhidaemyy_razdel:String(row.ozhidaemyy_razdel||''),ozhidaemyy_fakt:row.ozhidaemyy_fakt==null?null:String(row.ozhidaemyy_fakt),hits:[]});
  if(row.fragment_id){
    const sim=Number(row.shodstvo);
    if(!Number.isFinite(sim)) return fail('kb03b_similarity_invalid','Similarity не является конечным числом.',{vopros_id:qid,shodstvo:row.shodstvo});
    groups.get(qid).hits.push({
      fragment_id:String(row.fragment_id),nomer_fragmenta:Number(row.nomer_fragmenta),
      put_razdela:String(row.put_razdela||''),tekst_fragmenta:String(row.tekst_fragmenta||''),shodstvo:sim
    });
  }
}
const questions=[...groups.values()].sort((a,b)=>a.nomer-b.nomer);
if(questions.length<3||questions.length>10 || questions.some((q,i)=>q.nomer!==i+1)){
  return fail('kb03b_search_question_count','Draft search не сохранил последовательные 3..10 questions.',{count:questions.length});
}
for(const q of questions) q.hits.sort((a,b)=>b.shodstvo-a.shodstvo || a.nomer_fragmenta-b.nomer_fragmenta);
function qualifies(q,h){
  const exp=canon(q.ozhidaemyy_razdel), actual=canon(h.put_razdela);
  const section=actual===exp || actual.startsWith(exp+' ');
  if(!section) return false;
  if(!q.ozhidaemyy_fakt) return true;
  return canon(h.tekst_fragmenta).includes(canon(q.ozhidaemyy_fakt));
}
const matrix=[];
for(const thr of thresholds){
  let okCount=0;
  const per=[];
  for(const q of questions){
    const retained=q.hits.filter(h=>h.shodstvo>=thr);
    const match=retained.find(h=>qualifies(q,h))||null;
    const ok=Boolean(match);
    if(ok) okCount++;
    per.push({nomer:q.nomer,uspeshno:ok,matched_fragment:match?.nomer_fragmenta||null,matched_similarity:match?Number(match.shodstvo.toFixed(6)):null,returned:retained.length});
  }
  matrix.push({porog:Number(thr.toFixed(2)),uspeshnyh:okCount,vsego:questions.length,full_pass:okCount===questions.length,questions:per});
}
const passing=matrix.filter(x=>x.full_pass);
const selected=passing.length?passing[passing.length-1].porog:thresholds[0];
const selectedMatrix=matrix.find(x=>Math.abs(x.porog-selected)<1e-9);
const checks=[];
for(const q of questions){
  const retained=q.hits.filter(h=>h.shodstvo>=selected).slice(0,topK);
  const match=retained.find(h=>qualifies(q,h))||null;
  checks.push({
    vopros_id:q.vopros_id,
    porog_shodstva:selected,
    limit_rezultatov:topK,
    poluchennye_fragmenty:retained.map(h=>h.fragment_id),
    shodstva:retained.map(h=>Number(h.shodstvo.toFixed(12))),
    rezultat:match?'uspeshno':'neuspeshno',
    opisanie:match
      ?`Ожидаемый раздел/факт подтверждён fragment ${match.nomer_fragmenta}; similarity=${match.shodstvo.toFixed(6)}.`
      :`При пороге ${selected.toFixed(2)} ожидаемый раздел/факт не найден в top-${topK}.`
  });
}
const okCount=checks.filter(x=>x.rezultat==='uspeshno').length;
return [{json:{
  kb03b_ocenka_validna:true,
  kb03b_kod:okCount===questions.length?'draft_checks_full_pass':'draft_checks_not_full_pass',
  kb03b_opisanie:okCount===questions.length
    ?`Все ${questions.length} canonical questions прошли draft-only retrieval check.`
    :`Прошли ${okCount} из ${questions.length} canonical questions; версия должна остаться draft.`,
  kb03b_proverki:checks,
  kb03b_kalibrovka:{
    diapazon:thresholds,
    pravilo_vybora:'highest_grid_threshold_with_full_positive_reference_pass_else_0.45',
    vybrannyy_porog:selected,
    full_pass_threshold_exists:passing.length>0,
    matrix:matrix.map(x=>({porog:x.porog,uspeshnyh:x.uspeshnyh,vsego:x.vsego,full_pass:x.full_pass})),
    final_client_threshold_fixed:false,
    primechanie:'Это калибровка positive YAML reference questions; финальный client threshold требует также negative/no-answer набора.'
  },
  kb03b_search_otchet:{
    questions:questions.length,top_k:topK,uspeshnyh:okCount,vsego:questions.length,
    draft_only:true,version_scoped:true,profile_scoped:true,
    expected_section_and_fact_same_fragment:true,generative_llm_vyzovov:0,publish_vypolnen:false
  },
  kb03b_embedding_otchet:k.embedding_otchet||{},
  kb03b_job:{zadanie_id:k.zadanie_id,worker_id:k.worker_id,nomer_vladeniya:k.nomer_vladeniya,povtor_cherez_sekund:Number(k.povtor_cherez_sekund||300)},
  kb03b_version:{dokument_id:k.dokument_id,versiya_id:k.versiya_id,profil_indeksa_id:k.profil_indeksa_id,status_versii:k.status_versii}
}}];

