}

cfg.razreshennye_menedzhery_telegram_id = (cfg.menedzhery || [])
  .filter(m => m && m.aktiven === true && m.mozhet_zabirat === true)
  .map(m => Number(m.telegram_user_id))
  .filter(Number.isFinite);

return $input.all().map(i => ({
  json: {
