}));
})();
current=step0[0]?.json;
if(!current) return [];
const step1=(()=>{const $json=current;
const root=$json||{},b=root.body||{},m=b.message||null,cb=b.callback_query||null;
let tip='drugoe',chat=null,from=null,thread=null,text='',cbid=null,data='',sourceTime=null,chatType=null,doc=null;
