function sha256Hex(text) { return sha256Bytes(new TextEncoder().encode(text)); }


const sluzhebny={
  update_id:b.update_id,
  tip,
  chat_id:chat,
  chat_type:chatType,
  from_id:from,
  message_thread_id:thread,
  tekst:text,
  callback_query_id:cbid,
  callback_data:data,
  dokument:doc,
  raw:b
};
const db_sluzhebnoe_sobytie={
  versiya_formata:1,
  operaciya_id:'tg_service_ingress:'+accountId+':'+externalId,
  akkaunt_istochnika_id:accountId,
  vneshnee_sobytie_id:externalId,
