};
return [{json:{_nastroyki:cfg,sluzhebny,db_sluzhebnoe_sobytie}}];
})();
current=step1[0]?.json;
if(!current) return [];
return [{json:current}];

const x=$json||{},s=x.sluzhebny||{},cfg=x._nastroyki?.kb||{},d=s.dokument||{};
if(!['uspeshno','dublikat'].includes(String(x.rezultat||''))) return [];
if(String(x.tip_sobytiya||s.tip||'')!=='dokument_kb') return [];

const users=(cfg.razreshennye_otpraviteli_telegram_id||[]).map(String);
const chats=(cfg.razreshennye_lichnye_chat_id||[]).map(String);
const user=String(s.from_id??'');
const chat=String(s.chat_id??'');
const name=String(d.file_name||'').trim();
const declaredSize=Number(d.file_size??0);
const max=Number(cfg.max_bayt||5242880);

let ok=true,code='',message='';
if(cfg.vklyuchena!==true){
  ok=false; code='kb_otklyuchena'; message='Загрузка базы знаний сейчас отключена.';
}else if(!users.length||!chats.length){
  ok=false; code='kb_whitelist_ne_nastroen'; message='Загрузка базы знаний ещё не настроена: укажите разрешённый Telegram user ID и private chat ID в ноде «Настройки служебного бота».';
}else if(s.chat_type!=='private'){
  ok=false; code='kb_tolko_lichnyy_chat'; message='Базу знаний можно загружать только в личном чате со служебным ботом.';
}else if(!users.includes(user)||!chats.includes(chat)){
  ok=false; code='kb_otpravitel_ne_razreshen'; message='Этот Telegram-пользователь или чат не разрешён для загрузки базы знаний.';
}else if(!d.file_id){
  ok=false; code='kb_net_file_id'; message='Telegram не передал file_id документа.';
}else if(!name||!/\.md$/i.test(name)){
  ok=false; code='kb_tolko_md'; message='Разрешены только файлы с расширением .md.';
}else if(Number.isFinite(declaredSize)&&declaredSize>0&&declaredSize>max){
  ok=false; code='kb_fayl_slishkom_bolshoy'; message='Файл больше лимита 5 MiB и не будет скачан.';
}

return [{json:{
  ...x,
  kb01a_razresheno:ok,
  kb01a_kod:code||null,
  kb01a_otvet:message||null,
  kb01a_chat_id:s.chat_id,
  kb01a_file_id:d.file_id||null,
