  kb01a_declared_size:Number.isFinite(declaredSize)?declaredSize:null,
  kb01a_mime_type:d.mime_type||null,
  kb01a_max_bayt:max
}}];

const items=$input.all();
const out=[];
for(let i=0;i<items.length;i++){
  const item=items[i]||{json:{}};
  const j=item.json||{};
  try{
    const buf=await this.helpers.getBinaryDataBuffer(i,'data');
    const max=Number(j.kb01a_max_bayt||5242880);
    if(!buf||!buf.length){
      out.push({json:{...j,kb01a_binary_ok:false,kb01a_kod:'kb_pustoy_fayl',kb01a_otvet:'Файл пустой и не может быть принят в базу знаний.',kb01a_chat_id:j.kb01a_chat_id}});
      continue;
    }
    if(buf.length>max){
      out.push({json:{...j,kb01a_binary_ok:false,kb01a_kod:'kb_fayl_slishkom_bolshoy',kb01a_otvet:'Фактический размер файла больше лимита 5 MiB.',kb01a_chat_id:j.kb01a_chat_id}});
      continue;
    }
    out.push({json:{
      ...j,
      kb01a_binary_ok:true,
      kb01a_fakt_razmer:buf.length,
      kb01a_base64:buf.toString('base64')
    }});
  }catch(e){
    out.push({json:{
      ...j,
      kb01a_binary_ok:false,
      kb01a_kod:'kb_skachivanie_ne_udalos',
      kb01a_otvet:'Не удалось скачать документ из Telegram. Попробуйте отправить файл ещё раз.',
      kb01a_chat_id:j.kb01a_chat_id,
      kb01a_tehnicheskaya_oshibka:String(e?.message||e||'download_failed')
    }});
  }
}
return out;

