  const fileName = esc(k.kb01a_file_name || 'document.md');

  text =
    '✅ Markdown принят и долговечно зарегистрирован. ' +
    'Файл «' + fileName + '» поставлен в очередь базы знаний. ' +
    'Автоматическая обработка, проверка и публикация будут выполнены worker-цепочкой этого workflow.';
} else if (result === 'dublikat') {
  text =
    'ℹ️ Это Telegram-событие уже было зарегистрировано. ' +
    'Повторная загрузка не создана.';
} else {
  const code = esc(r.kod_oshibki || 'kb_registration_error');
  const desc = esc(r.opisanie || 'Загрузка не зарегистрирована.');

  text =
    '❌ Документ не принят в очередь знаний. ' +
    desc +
    ' Код: ' +
    code;
}

return [{
  json: {
    ...k,
    kb01a_chat_id: s.chat_id ?? k.kb01a_chat_id ?? null,
    kb01a_otvet: text,
    kb01a_rezultat: {
      rezultat: r.rezultat || null,
      kod_oshibki: r.kod_oshibki || null,
      zagruzka_id: r.zagruzka_id || null,
      zadanie_id: r.zadanie_id || null,
      status_zagruzki: r.status_zagruzki || null
    }
  }
}];

const x=$json||{},s=x.sluzhebny||{},cfg=x._nastroyki||{};
if(!['uspeshno','dublikat'].includes(String(x.rezultat||''))) return [];
if(String(x.tip_sobytiya||s.tip||'')!=='callback_take') return [];

const data=String(s.callback_data||'');
const m=/^take:([0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12})$/i.exec(data);
if(!m){
  return [{json:{
    take_lokalno_otkloneno:true,
    callback_query_id:s.callback_query_id||null,
    tekst_callback:'Некорректная кнопка: запросите новую кнопку захвата.',
    _take_kontekst:{callback_query_id:s.callback_query_id||null}
  }}];
}

const managers=Array.isArray(cfg.menedzhery)?cfg.menedzhery:[];
const allowed=managers
  .filter(v=>v&&v.aktiven===true&&v.mozhet_zabirat===true)
  .map(v=>String(v.telegram_user_id));

const user=String(s.from_id??'');
const expectedChat=String(cfg.sluzhebnaya_gruppa_id??'');
const actualChat=String(s.chat_id??'');

if(!allowed.includes(user)||!user||!expectedChat||actualChat!==expectedChat||!s.message_thread_id||!s.callback_query_id){
  return [{json:{
    take_lokalno_otkloneno:true,
    callback_query_id:s.callback_query_id||null,
    tekst_callback:'Не удалось забрать диалог: действие не разрешено.',
    _take_kontekst:{callback_query_id:s.callback_query_id||null}
  }}];
}

const ctx={
  callback_query_id:String(s.callback_query_id),
  sobytie_id:String(x.sobytie_id),
  dialog_id:m[1],
  telegram_user_id:user,
  message_thread_id:String(s.message_thread_id)
};

const managerSync={
  operaciya_id:'manager_sync:'+String(x.sobytie_id),
  menedzhery:managers.map(v=>({
    telegram_user_id:String(v.telegram_user_id),
    otobrazhaemoe_imya:String(v.otobrazhaemoe_imya||'Менеджер'),
    aktiven:v.aktiven!==false,
    mozhet_zabirat:v.mozhet_zabirat!==false,
    mozhet_vozvrashchat:v.mozhet_vozvrashchat!==false,
    lichnye_uvedomleniya:v.lichnye_uvedomleniya!==false,
    prioritet_naznacheniya:Number.isFinite(Number(v.prioritet_naznacheniya))
      ?Number(v.prioritet_naznacheniya):100
  }))
};

return [{json:{
  ...x,
  take_lokalno_otkloneno:false,
  _take_kontekst:ctx,
  manager_sync_payload:managerSync,
  take_payload:{
    operaciya_id:'take:'+String(x.sobytie_id),
    sobytie_id:String(x.sobytie_id),
    dialog_id:m[1],
    telegram_user_id:user,
    ozhidaemaya_versiya_dialoga:1
  }
}}];

const x=$json||{};
const ctx=x._take_kontekst||{};
let text='Не удалось забрать диалог.';
if(x.take_lokalno_otkloneno===true){text=String(x.tekst_callback||'Действие не разрешено.');}
else if(x.rezultat==='uspeshno'&&x.vladelec==='chelovek'){text='Диалог закреплён за вами';}
else if(x.rezultat==='dublikat'&&x.vladelec==='chelovek'){text='Диалог уже закреплён за вами';}
else if(x.kod_oshibki==='dialog_uzhe_zanyat'){text='Диалог уже забрал другой менеджер';}
else if(x.kod_oshibki==='stale_dialog_version'){text='Диалог изменился. Нажмите «Забрать диалог» ещё раз.';}
else if(x.kod_oshibki==='menedzher_ne_razreshen'){text='У вас нет права забрать этот диалог';}
else if(x.kod_oshibki==='dialog_zavershen'){text='Диалог уже завершён';}
else if(x.opisanie){text=String(x.opisanie).slice(0,180);}
return [{json:{
  ...x,
  callback_query_id:ctx.callback_query_id||x.callback_query_id||null,
  tekst_callback:text,
  zahvat_uspeshnyy:['uspeshno','dublikat'].includes(String(x.rezultat||''))&&x.vladelec==='chelovek',
  novyy_zahvat:String(x.rezultat||'')==='uspeshno'&&x.vladelec==='chelovek'
}}];

const x=$json||{}, s=x.sluzhebny||{}, cfg=x._nastroyki||{};

if(!['uspeshno','dublikat'].includes(String(x.rezultat||''))) return [];
if(String(x.tip_sobytiya||s.tip||'')!=='operator_message') return [];

const text=String(s.tekst||'').trim();
const user=String(s.from_id??'');
const chat=String(s.chat_id??'');
const thread=String(s.message_thread_id??'');
const expectedChat=String(cfg.sluzhebnaya_gruppa_id??'');
const managers=Array.isArray(cfg.menedzhery)?cfg.menedzhery:[];

const configuredManager=managers.find(m =>
  m &&
  m.aktiven===true &&
  String(m.telegram_user_id)===user
);

let ok=true, code=null, message=null;

if(!text){
  ok=false; code='pustoy_tekst'; message='Пустое сообщение не отправляется клиенту.';
}else if(!user || !thread || !expectedChat || chat!==expectedChat){
  ok=false; code='ne_sluzhebnaya_tema'; message='Сообщение должно быть написано в теме клиента служебной группы.';
}else if(!configuredManager){
  ok=false; code='menedzher_ne_razreshen'; message='Этот сотрудник не зарегистрирован как активный менеджер компании.';
}

return [{json:{
  ...x,
  manager_reply_lokalno_razresheno:ok,
  manager_reply_kod:code,
  manager_reply_opisanie:message,
  manager_reply_context:{
    sobytie_id:String(x.sobytie_id||''),
    telegram_user_id:user,
    sluzhebnyy_chat_id:chat,
    message_thread_id:thread,
    tekst:text
  }
}}];

const x=$json||{},s=x.sluzhebny||{},cfg=x._nastroyki||{};
if(!['uspeshno','dublikat'].includes(String(x.rezultat||''))) return [];
if(String(x.tip_sobytiya||s.tip||'')!=='start') return [];
if(String(s.chat_type||'')!=='private') return [];

const user=String(s.from_id??'');
const chat=String(s.chat_id??'');
const managers=Array.isArray(cfg.menedzhery)?cfg.menedzhery:[];
const allowed=managers.some(v=>v&&v.aktiven===true&&String(v.telegram_user_id)===user);

const managerSync={
  operaciya_id:'manager_sync_start:'+String(x.sobytie_id),
  menedzhery:managers.map(v=>({
    telegram_user_id:String(v.telegram_user_id),
    otobrazhaemoe_imya:String(v.otobrazhaemoe_imya||'Менеджер'),
    aktiven:v.aktiven!==false,
    mozhet_zabirat:v.mozhet_zabirat!==false,
    mozhet_vozvrashchat:false,
    lichnye_uvedomleniya:v.lichnye_uvedomleniya!==false,
    prioritet_naznacheniya:Number.isFinite(Number(v.prioritet_naznacheniya))
      ?Number(v.prioritet_naznacheniya):100
  }))
};

return [{json:{
  ...x,
  start_lokalno_razreshen:Boolean(allowed&&user&&chat),
  start_chat_id:chat,
  start_user_id:user,
  manager_sync_payload:managerSync,
  start_context:{
    sobytie_id:String(x.sobytie_id||''),
    telegram_user_id:user,
    private_chat_id:chat
  }
}}];

